<js>
result.toArray().map(el=>{
    var url=String(el.select('a+a').attr('href'));
    var J=org.jsoup.Jsoup.parse(java.ajax('https://www.miaojiang8.net'+url));
    var og=selector=>String(J.select('[property="og:'+selector+'"]').attr('content'));
    return{
        name:og('novel:book_name'),
        author:og('novel:author'),
        kind:og('novel:status')+','+og('novel:update_time').replace(/\s.*/,''),
        latest:og('novel:latest_chapter_name'),
        intro:og('description'),
        cover:og('image'),
        url:'https://www.miaojiang8.net'+url,
    };
});
</js>

p[:2]<js>
result.toArray().map(el=>{
    var url=String(el.select('a+a').attr('href')).replace(/^/,'https://www.qianxuntxt.com');
    var J=org.jsoup.Jsoup.parse(java.ajax(url));
    var og=selector=>String(J.select('[property="og:'+selector+'"]').attr('content'));
    return{
        name:og('novel:book_name'),
        author:og('novel:author'),
        kind:og('novel:category').replace(/小说/,'')+','+og('novel:status').replace(/中|已/,'')+','+og('novel:update_time').replace(/\s.*/,''),
        latest:og('novel:latest_chapter_name'),
        intro:og('description'),
        cover:og('image'),
        url:url,
    };
});
</js>

@js:
var list=[];
var reg=new RegExp(/s1"><a.href="([^"]+)[\s\S]+?>([^<]+)[\s\S]+?s2.+?>([^<]+)[\s\S]+?s3.+?>([^<]+)[\s\S]+?s4.+?>([^<]+)[\s\S]+?s5.+?>[^<]+[\s\S]+?s6.+?>([^<]+)/g);
var tmp,cover;
while((tmp=reg.exec(result))){
//封面链接
cover=(tmp[1].match(/d{1,2}/)) ? (tmp[1].replace(/\/(\d+)\//,'/files/article/image/0/$1/$1s.jpg')):(tmp[1].replace(/\/((\d*)\d{3})\//,'/files/article/image/$2/$1/$1s.jpg').replace(/\/\//,'/0/'));

list.push({q:tmp[2],w:tmp[4],e2:tmp[5]+'字',e1:tmp[6],r:tmp[3],t:cover,y:tmp[1]});
}list;

